CREATE INDEX IF NOT EXISTS idx_mail_messages_metadata_updated_at ON messaging.mail_messages ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION messaging.mail_messages_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS mail_messages_insert_audit ON messaging.mail_messages;
CREATE TRIGGER mail_messages_insert_audit BEFORE INSERT ON messaging.mail_messages
    FOR EACH ROW EXECUTE FUNCTION messaging.mail_messages_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS mail_messages_update_audit ON messaging.mail_messages;
CREATE TRIGGER mail_messages_update_audit BEFORE UPDATE ON messaging.mail_messages
    FOR EACH ROW EXECUTE FUNCTION messaging.mail_messages_audit_timestamp();
